mapper.select:
SELECT qi.id,qi.main_id, qb.purchase_order_id, qb.warehouse_id, qi.purchase_order_detail_id, qi.qc_type,qi.total_qty FROM qc_info qb INNER JOIN qc_result qi ON qi.main_id=qb.id AND qi.is_deleted=false WHERE qi.is_deleted=false
AND qb.id IN
#{mainId}

select qi.source_detail_id, sum(lot_qualified_qty) as totalLotQualifiedQty from qc_result qr inner join qc_info qi on qi.id = qr.main_id and qi.is_deleted = FALSE where qr.is_deleted = FALSE and qi.qc_status = 'finishQc' and qi.source_detail_id in
#{sourceDetailId}
group by qi.source_detail_id
